class Solution {
    public int largestComponentSize(int[] nums) {
        int n = nums.length;
        UnionFind uf = new UnionFind(n);
        // Map from prime factor to the index of the number in nums
        Map<Integer, Integer> factorToIndex = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int num = nums[i];
            // Get factors larger than 1, as prime factors
            for (int factor : primeFactors(num)) {
                if (!factorToIndex.containsKey(factor)) {
                    factorToIndex.put(factor, i);
                } else {
                    uf.union(i, factorToIndex.get(factor));
                }
            }
        }

        int[] counts = new int[n];
        int maxSize = 0;
        for (int i = 0; i < n; i++) {
            int root = uf.find(i);
            counts[root]++;
            maxSize = Math.max(maxSize, counts[root]);
        }
        return maxSize;
    }

    private List<Integer> primeFactors(int num) {
        List<Integer> factors = new ArrayList<>();
        int d = 2;
        while (d * d <= num) {
            if (num % d == 0) {
                factors.add(d);
                while (num % d == 0) num /= d;
            }
            d++;
        }
        if (num > 1) factors.add(num);
        return factors;
    }

    private static class UnionFind {
        int[] parent, rank;
        UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA != rootB) {
                if (rank[rootA] < rank[rootB]) {
                    parent[rootA] = rootB;
                } else if (rank[rootA] > rank[rootB]) {
                    parent[rootB] = rootA;
                } else {
                    parent[rootB] = rootA;
                    rank[rootA]++;
                }
            }
        }
    }
}

